414: func (c *DockerServiceController) restoreServices(ctx context.Context, ids []services.ID) error {
415: 	var restoreErrs []error
416: 	for _, id := range ids {
417: 		svc, ok := c.catalog.Get(id)
418: 		if !ok {
419: 			continue
420: 		}
421: 		if _, err := c.runCompose(ctx, "restart", string(id)); err != nil {
422: 			restoreErrs = append(restoreErrs, fmt.Errorf("restart %s: %w", id, err))
423: 			continue
424: 		}
425: 		if err := c.waitReady(ctx, svc); err != nil {
426: 			restoreErrs = append(restoreErrs, fmt.Errorf("wait for %s after restart: %w", id, err))
427: 		}
428: 	}
429: 	return errors.Join(restoreErrs...)
