1277: 		s.writeError(w, http.StatusConflict, helperproto.CodeServiceConflict, err.Error())
1278: 	case errors.Is(err, helperproto.ErrNotImplemented):
1279: 		s.writeError(w, http.StatusNotImplemented, helperproto.CodeNotImplemented, err.Error())
1280: 	case errors.Is(err, helperproto.ErrInvalidRequest):
1281: 		s.writeError(w, http.StatusBadRequest, helperproto.CodeInvalidRequest, err.Error())
1282: 	case errors.Is(err, helperproto.ErrUnauthorized):
1283: 		s.writeError(w, http.StatusForbidden, helperproto.CodeUnauthorized, err.Error())
1284: 	case errors.Is(err, helperproto.ErrServingModeUnavailable):
1285: 		s.writeError(w, http.StatusConflict, helperproto.CodeServingModeUnavailable, err.Error())
1286: 	case errors.Is(err, helperproto.ErrVhostIncludeMissing):
1287: 		s.writeError(w, http.StatusConflict, helperproto.CodeVhostIncludeMissing, err.Error())
1288: 	case errors.Is(err, helperproto.ErrVhostSyncBusy):
1289: 		s.writeError(w, http.StatusConflict, helperproto.CodeVhostSyncBusy, err.Error())
1290: 	case errors.Is(err, helperproto.ErrVhostConfigInvalid):
1291: 		s.writeError(w, http.StatusUnprocessableEntity, helperproto.CodeVhostConfigInvalid, err.Error())
1292: 	case errors.Is(err, helperproto.ErrServerReloadFailed):
1293: 		s.writeError(w, http.StatusBadGateway, helperproto.CodeServerReloadFailed, err.Error())
1294: 	case errors.Is(err, helperproto.ErrVhostSyncFailed):
1295: 		s.writeError(w, http.StatusInternalServerError, helperproto.CodeVhostSyncFailed, err.Error())
1296: 	case errors.Is(err, helperproto.ErrToolConflict):
1297: 		s.writeError(w, http.StatusConflict, helperproto.CodeToolConflict, err.Error())
