1315: func decodeJSON(w http.ResponseWriter, r *http.Request, dst any) error {
1316: 	defer func() { _ = r.Body.Close() }()
1317: 	r.Body = http.MaxBytesReader(w, r.Body, maxRequestBody)
1318: 	dec := json.NewDecoder(r.Body)
1319: 	if err := dec.Decode(dst); err != nil {
1320: 		if errors.Is(err, io.EOF) {
1321: 			return errors.New("request body is empty")
1322: 		}
1323: 		return fmt.Errorf("decode request: %w", err)
1324: 	}
1325: 	var extra any
1326: 	if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
1327: 		return errors.New("request body contains trailing data")
1328: 	}
1329: 	return nil
