364: func (c *Client) do(ctx context.Context, method, path string, in, out any) error {
365: 	var body io.Reader
366: 	if in != nil {
367: 		data, err := json.Marshal(in)
368: 		if err != nil {
369: 			return fmt.Errorf("helperclient: encode %s request: %w", path, err)
370: 		}
371: 		body = bytes.NewReader(data)
372: 	}
373: 	req, err := http.NewRequestWithContext(ctx, method, baseURL+path, body)
374: 	if err != nil {
375: 		return fmt.Errorf("helperclient: build %s request: %w", path, err)
376: 	}
377: 	req.Header.Set(helperproto.ProtocolHeader, helperproto.Version)
378: 	if in != nil {
379: 		req.Header.Set("Content-Type", "application/json")
380: 	}
381: 	resp, err := c.http.Do(req)
382: 	if err != nil {
383: 		return fmt.Errorf("helperclient: %s %s: %w", method, path, err)
384: 	}
385: 	defer func() { _ = resp.Body.Close() }()
386: 
387: 	if resp.StatusCode < http.StatusOK || resp.StatusCode >= http.StatusMultipleChoices {
388: 		return decodeError(resp)
389: 	}
390: 	if out == nil {
391: 		_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, maxResponseBody))
392: 		return nil
393: 	}
394: 	if err := json.NewDecoder(io.LimitReader(resp.Body, maxResponseBody)).Decode(out); err != nil {
395: 		return fmt.Errorf("helperclient: decode %s response: %w", path, err)
396: 	}
397: 	return nil
398: }
399: 
400: func decodeError(resp *http.Response) error {
401: 	data, readErr := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
402: 	payload := helperproto.ErrorResponse{}
403: 	if len(bytes.TrimSpace(data)) > 0 {
404: 		_ = json.Unmarshal(data, &payload)
405: 	}
406: 	if payload.Code == "" {
407: 		payload.Code = codeForStatus(resp.StatusCode)
408: 	}
409: 	if payload.Message == "" {
410: 		if readErr != nil {
411: 			payload.Message = readErr.Error()
412: 		} else {
413: 			payload.Message = strings.TrimSpace(string(data))
414: 		}
415: 		if payload.Message == "" {
416: 			payload.Message = http.StatusText(resp.StatusCode)
417: 		}
418: 	}
419: 	return &Error{Status: resp.StatusCode, Code: payload.Code, Message: payload.Message}
420: }
421: 
422: func codeForStatus(status int) string {
423: 	switch status {
424: 	case http.StatusForbidden:
425: 		return helperproto.CodeUnauthorized
426: 	case http.StatusUpgradeRequired:
427: 		return helperproto.CodeProtocolMismatch
428: 	case http.StatusBadRequest, http.StatusRequestEntityTooLarge:
429: 		return helperproto.CodeInvalidRequest
430: 	case http.StatusNotImplemented:
431: 		return helperproto.CodeNotImplemented
432: 	default:
433: 		return helperproto.CodeInternal
434: 	}
435: }

