102: func (f *fakeCommandRunner) Run(ctx context.Context, name string, args ...string) ([]byte, error) {
103: 	call := append([]string{name}, args...)
104: 	f.mu.Lock()
105: 	f.calls = append(f.calls, call)
106: 	handle := f.handle
107: 	f.mu.Unlock()
108: 	if handle != nil {
109: 		return handle(name, args)
110: 	}
111: 	return []byte("ok"), nil
112: }
