114: func (f *fakeCommandRunner) snapshot() [][]string {
115: 	f.mu.Lock()
116: 	defer f.mu.Unlock()
117: 	out := make([][]string, len(f.calls))
118: 	for i := range f.calls {
119: 		out[i] = append([]string(nil), f.calls[i]...)
120: 	}
121: 	return out
122: }
