264: func (s *dockerSim) psOutput() []byte {
265: 	merged := make(map[services.ID]simContainer, len(s.containers))
266: 	for id, cont := range s.containers {
267: 		merged[id] = cont
268: 	}
269: 	ids := make([]services.ID, 0, len(s.psOverrides))
270: 	for id := range s.psOverrides {
271: 		ids = append(ids, id)
272: 	}
273: 	sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })
274: 	for _, id := range ids {
275: 		seq := s.psOverrides[id]
276: 		if len(seq) == 0 {
277: 			continue
278: 		}
279: 		item := seq[0]
280: 		s.psOverrides[id] = seq[1:]
281: 		if item.State == "" {
282: 			delete(merged, id)
283: 			continue
284: 		}
285: 		merged[id] = item
286: 	}
287: 
288: 	entries := make([]psEntry, 0, len(merged))
289: 	for id, cont := range merged {
290: 		entries = append(entries, psEntry{
291: 			ID:      cont.ID,
292: 			Name:    "devstack-" + string(id),
293: 			Service: string(id),
294: 			State:   cont.State,
295: 			Health:  cont.Health,
296: 		})
297: 	}
298: 	sort.Slice(entries, func(i, j int) bool { return entries[i].Service < entries[j].Service })
299: 	data, _ := json.Marshal(entries)
300: 	return data
301: }
