303: func (s *dockerSim) run(name string, args []string) ([]byte, error) {
304: 	s.mu.Lock()
305: 	defer s.mu.Unlock()
306: 
307: 	if name == "docker" && len(args) >= 3 && args[0] == "image" && args[1] == "inspect" {
308: 		if s.inspectErr != nil {
309: 			return nil, s.inspectErr
310: 		}
311: 		image := args[2]
312: 		if s.images[image] {
313: 			return []byte("[]"), nil
314: 		}
315: 		return nil, fmt.Errorf("docker image inspect: Error response from daemon: No such image: %s", image)
316: 	}
317: 
318: 	if name != "docker" || len(args) < 6 || args[0] != "compose" {
319: 		return nil, fmt.Errorf("unexpected command: %s %v", name, args)
320: 	}
321: 	sub := args[5]
322: 	last := ""
323: 	if len(args) > 6 {
324: 		last = args[len(args)-1]
325: 	}
326: 	switch sub {
327: 	case "ps":
328: 		s.psCalls++
329: 		if s.psErr != nil {
330: 			return nil, s.psErr
331: 		}
332: 		if len(s.psRaw) > 0 {
333: 			return append([]byte(nil), s.psRaw...), nil
334: 		}
335: 		return s.psOutput(), nil
336: 	case "pull":
337: 		if s.pullErr != nil {
338: 			return nil, s.pullErr
339: 		}
340: 	case "stop":
341: 		if s.stopErr != nil {
342: 			if s.stopAppliedOnErr {
343: 				s.removeContainer(services.ID(last))
344: 			}
345: 			return nil, s.stopErr
346: 		}
347: 		s.removeContainer(services.ID(last))
348: 		if s.onStop != nil {
349: 			s.onStop()
350: 		}
351: 	case "up":
352: 		if s.upErr != nil {
353: 			return nil, s.upErr
354: 		}
355: 		s.startContainer(services.ID(last))
356: 	case "restart":
357: 		if s.restartErr != nil {
358: 			return nil, s.restartErr
359: 		}
360: 		s.startContainer(services.ID(last))
361: 	case "rm":
362: 		if s.rmErr != nil {
363: 			return nil, s.rmErr
364: 		}
365: 		s.removeContainer(services.ID(last))
366: 	case "exec":
367: 		if s.execErr != nil {
368: 			return nil, s.execErr
369: 		}
370: 		return []byte("ok"), nil
371: 	case "logs":
372: 		return []byte("logs"), nil
373: 	default:
374: 		return nil, fmt.Errorf("unexpected compose subcommand %q", sub)
375: 	}
376: 	return []byte("ok"), nil
377: }
