// databaseLock returns the per-service mutation lock. Database streams never
// hold the global operation lock.
func (c *DockerServiceController) databaseLock(serviceID string) *syncMutex {
	value, _ := c.databaseLocks.LoadOrStore(serviceID, &syncMutex{})
	return value.(*syncMutex)
}

// syncMutex is a small alias to keep databaseLock's signature readable while
// avoiding a second sync import in callers.
type syncMutex = struct {
	mu chan struct{}
}

