type fakeCommandRunner struct {
	mu           sync.Mutex
	calls        [][]string
	stdin        [][]byte
	streamOutput []byte
	psState      string
	aclList      string
	handle       func(name string, args []string) ([]byte, error)
	handleInput  func(name string, args []string, input []byte) ([]byte, error)
}

func (f *fakeCommandRunner) aclListOutput() []byte {
