    } else if req.PreImportBackup {
        preJob...
    }
    lock...
    if mode == replace { drop/create -> failedJob(..., preBackupID) }
    if err := runEngineInput(... reader ...); err != nil { return failedJob(..., preBackupID, ...), err }
